<?php declare(strict_types=1); require __DIR__.'/_guard.php'; require __DIR__.'/lib.php'; require_case(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow,noarchive"><title>My test results</title>
<style>
:root{--bg:#fbf9f7;--card:#fff;--ink:#241f1c;--soft:#6d635c;--line:#e6dfd8;--accent:#a8433a;--r:14px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,sans-serif}.wrap{max-width:720px;margin:auto;padding:24px 16px 60px}.back{color:var(--accent);text-decoration:none;font-weight:650}h1{margin:18px 0 4px}.lede,.muted{color:var(--soft)}.card{margin-top:18px;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:18px}label{display:block;margin:12px 0 0;font-weight:650}input,select{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid var(--line);border-radius:8px;font:inherit}button{margin-top:18px;padding:11px 16px;background:var(--accent);color:#fff;border:0;border-radius:8px;font:inherit;font-weight:700}.result{border-top:1px solid var(--line);padding:14px 0}.result:first-child{border-top:0}.row{display:flex;justify-content:space-between;gap:12px}.pill{font-size:.78rem;color:var(--soft);border:1px solid var(--line);border-radius:999px;padding:2px 8px;white-space:nowrap}.notice{background:#fdf3e7;border:1px solid #d89a54;border-radius:8px;padding:10px;color:#70400e}#message{min-height:24px;color:var(--accent);font-weight:650}
</style></head><body><main class="wrap"><a class="back" href="/app/">← My private records</a><h1>My test results</h1><p class="lede">Record each value exactly as it appears on your report. The original name and unit stay intact. A test is not treated as a standard identity until there is an exact verified match.</p>
<section class="card"><div class="notice">This is a factual record, not an interpretation or diagnosis. Add only information you can see on your report.</div>
<form id="resultForm"><label>Report date<input name="observed_on" type="date" required></label><label>Test name exactly as printed<input name="reported_test_name" maxlength="500" required></label><label>Result exactly as printed<input name="reported_value_text" maxlength="500" required></label><label>Unit (if printed)<input name="reported_unit" maxlength="120"></label><label>Specimen (if printed)<input name="reported_specimen_text" maxlength="255" placeholder="For example: serum, plasma, urine"></label><label>Laboratory (if printed)<input name="laboratory_name" maxlength="255"></label><label>Reference range exactly as printed<input name="reported_reference_range_text" maxlength="500"></label><label>Source laboratory report<select name="source_document_id" id="documents"><option value="">Not uploaded / add later</option></select></label><button type="submit">Save exact result</button><p id="message" role="status"></p></form></section>
<section class="card"><h2>Recorded results</h2><p class="muted">Unlinked means the report line is saved but has not been connected to a verified standard test identity.</p><div id="results">Loading…</div></section></main>
<script>
const api='test-results-api.php';
async function get(a){const r=await fetch(api+'?action='+a);return r.json()}
function esc(s){const d=document.createElement('div');d.textContent=s??'';return d.innerHTML}
function render(rows){const out=document.querySelector('#results');if(!rows.length){out.innerHTML='<p class="muted">No test results recorded yet.</p>';return}out.innerHTML=rows.map(x=>'<article class="result"><div class="row"><b>'+esc(x.reported_test_name)+'</b><span class="pill">'+esc(x.identity_status)+'</span></div><div><strong>'+esc(x.reported_value_text)+'</strong>'+(x.reported_unit?' '+esc(x.reported_unit):'')+'</div><div class="muted">'+esc(x.observed_on)+(x.reported_specimen_text?' · '+esc(x.reported_specimen_text):'')+(x.reported_reference_range_text?' · range: '+esc(x.reported_reference_range_text):'')+'</div></article>').join('')}
async function load(){const [r,d]=await Promise.all([get('list'),get('documents')]);const sel=document.querySelector('#documents');d.documents.forEach(x=>sel.insertAdjacentHTML('beforeend','<option value="'+x.document_id+'">'+esc(x.original_filename||'Laboratory report')+(x.document_date?' · '+esc(x.document_date):'')+'</option>'));render(r.results)}
document.querySelector('#resultForm').addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const m=document.querySelector('#message');m.textContent='Saving…';const r=await fetch(api+'?action=save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(f)});const j=await r.json();if(!j.ok){m.textContent=j.error;return}m.textContent='Saved. It is awaiting an exact identity match.';e.target.reset();render((await get('list')).results)});load();
</script></body></html>